import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IPostIntentHookV2 } from "./IPostIntentHookV2.sol";
import { IIntentLifecycleHook } from "./IIntentLifecycleHook.sol";
